from pathlib import Path
import base64,zlib

PAYLOAD=''
Path('src/lib/expanded-course-data.ts').write_text(zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))

def replace_once(path,old,new):
 p=Path(path); t=p.read_text();
 if old not in t: raise SystemExit(f'pattern not found: {path} :: {old[:80]}')
 p.write_text(t.replace(old,new,1))

# vocational data: merge 20 new courses
p=Path('src/lib/vocational-data.ts'); t=p.read_text()
if "expanded-course-data" not in t:
 t="import { EXTRA_VOCATIONAL_COURSES } from '@/lib/expanded-course-data';\n"+t
 t=t.replace('export const VOCATIONAL_COURSES: VocationalCourse[] = [','const BASE_VOCATIONAL_COURSES: VocationalCourse[] = [',1)
 idx=t.rfind('];')
 t=t[:idx+2]+"\n\nexport const VOCATIONAL_COURSES: VocationalCourse[] = [...BASE_VOCATIONAL_COURSES, ...EXTRA_VOCATIONAL_COURSES];\n"+t[idx+2:]
 p.write_text(t)

# area match: add 20 areas and 3 specific questions each; make them influence the score
p=Path('src/lib/area-match-data.ts'); t=p.read_text()
if "EXTRA_ACADEMIC_AREAS" not in t:
 t="import { EXTRA_ACADEMIC_AREAS, EXTRA_AREA_QUESTIONS } from '@/lib/expanded-course-data';\n"+t
 t=t.replace('const RAW = [','const RAW = [\n  ...EXTRA_ACADEMIC_AREAS,',1)
 old="""export function questionsForArea(area: AcademicArea): AreaQuestion[] {\n  return [...AREA_QUESTIONS,\n    { id:'area_depth', text:`Quanto você quer que ${area.courses} seja o centro da sua experiência universitária desde o início?`, dimension:'rigor', low:'Quero explorar', high:'Quero especialização' },\n    { id:'area_environment', text:`Quanto você se identifica com ambientes profissionais ligados a ${area.name}?`, dimension:'practical', low:'Ainda explorando', high:'Muito identificado' },\n  ];\n}\n\nexport function calculateAreaMatches(area: AcademicArea, answers: Record<string, number>) {\n  const student: Record<string, number> = {};\n  DIMENSIONS.forEach((dimension) => {\n    const values = Object.entries(answers).filter(([id]) => id === dimension || (id === 'area_depth' && dimension === 'rigor') || (id === 'area_environment' && dimension === 'practical')).map(([,value]) => value);\n    student[dimension] = values.length ? values.reduce((a,b)=>a+b,0) / values.length * 20 : 60;\n  });"""
 new="""export function questionsForArea(area: AcademicArea): AreaQuestion[] {\n  return [...AREA_QUESTIONS,\n    { id:'area_depth', text:`Quanto você quer que ${area.courses} seja o centro da sua experiência universitária desde o início?`, dimension:'rigor', low:'Quero explorar', high:'Quero especialização' },\n    { id:'area_environment', text:`Quanto você se identifica com ambientes profissionais ligados a ${area.name}?`, dimension:'practical', low:'Ainda explorando', high:'Muito identificado' },\n    ...(EXTRA_AREA_QUESTIONS[area.id] ?? []),\n  ];\n}\n\nexport function calculateAreaMatches(area: AcademicArea, answers: Record<string, number>) {\n  const student: Record<string, number> = {};\n  const questionMap = new Map(questionsForArea(area).map((question) => [question.id, question.dimension]));\n  DIMENSIONS.forEach((dimension) => {\n    const values = Object.entries(answers).filter(([id]) => questionMap.get(id) === dimension).map(([,value]) => value);\n    student[dimension] = values.length ? values.reduce((a,b)=>a+b,0) / values.length * 20 : 60;\n  });"""
 if old not in t: raise SystemExit('area questions block not found')
 t=t.replace(old,new,1); p.write_text(t)

